script:
(function () {
  'use strict';
  // Beneficiary (inherited IRA / plan) RMD schedule. Works out the beneficiary class and payout
  // rule, then projects required withdrawals: RMD = balance on Dec 31 of the prior year / divisor;
  // next balance = balance x (1 + return) - withdrawal; the final-year withdrawal empties the account.
  // Checked in Node against Pub. 590-B and the final regulations (scratchpad tests):
  //  - Table I values parsed from the Pub. 590-B (2025) text and compared value by value (ages 0-120);
  //    Pub. examples: age 57 -> 29.8; owner died 2021, beneficiary 55 in 2022 -> 2026 divisor 27.6.
  //  - Default case: owner born 3/15/1945 (RBD April 1, 2016) dies 9/10/2024, adult child born 1975:
  //    10-year rule with annual RMDs, divisor 2026 = max(36.2 - 1, 11.9 - 2) = 35.2,
  //    $400,000 / 35.2 = $11,363.64; account empty by 2034.
  //  - Owner died before the RBD: 10-year rule with no annual RMDs; estate -> 5-year rule (death in
  //    2022 -> empty by 2027, as in Treas. Reg. 1.401(a)(9)-3(c)(2)); minor child turning 21 in 2024
  //    -> empty by 2034 (Treas. Reg. 1.401(a)(9)-4(e)(9) Example 2); spouse delay to the owner's
  //    applicable-age year (Pub. 590-B Example 1: owner died 2022 at 65 -> 2030).
  // ---- IRS inherited-account RMD rules (distribution years 2025 and 2026) -----------------
  // Single Life Table: IRS Pub. 590-B (2025), Appendix B, Table I (Treas. Reg. 1.401(a)(9)-9(b)),
  // in effect for distribution years 2022 and later. Index = age reached in the distribution year.
  var SINGLE_LIFE = [
    84.6, 83.7, 82.8, 81.8, 80.8, 79.8, 78.8, 77.9, 76.9, 75.9,  // ages 0-9
    74.9, 73.9, 72.9, 71.9, 70.9, 69.9, 69.0, 68.0, 67.0, 66.0,  // ages 10-19
    65.0, 64.1, 63.1, 62.1, 61.1, 60.2, 59.2, 58.2, 57.3, 56.3,  // ages 20-29
    55.3, 54.4, 53.4, 52.5, 51.5, 50.5, 49.6, 48.6, 47.7, 46.7,  // ages 30-39
    45.7, 44.8, 43.8, 42.9, 41.9, 41.0, 40.0, 39.0, 38.1, 37.1,  // ages 40-49
    36.2, 35.3, 34.3, 33.4, 32.5, 31.6, 30.6, 29.8, 28.9, 28.0,  // ages 50-59
    27.1, 26.2, 25.4, 24.5, 23.7, 22.9, 22.0, 21.2, 20.4, 19.6,  // ages 60-69
    18.8, 18.0, 17.2, 16.4, 15.6, 14.8, 14.1, 13.3, 12.6, 11.9,  // ages 70-79
    11.2, 10.5, 9.9, 9.3, 8.7, 8.1, 7.6, 7.1, 6.6, 6.1,  // ages 80-89
    5.7, 5.3, 4.9, 4.6, 4.3, 4.0, 3.7, 3.4, 3.2, 3.0,  // ages 90-99
    2.8, 2.6, 2.5, 2.3, 2.2, 2.1, 2.1, 2.1, 2.0, 2.0,  // ages 100-109
    2.0, 2.0, 2.0, 1.9, 1.9, 1.8, 1.8, 1.6, 1.4, 1.1,  // ages 110-119
    1.0  // ages 120-120
  ];
  // Owner's applicable age (SECURE Act 2019, SECURE 2.0 Act 2022): 70 1/2 if born before
  // July 1, 1949; 72 if born July 1, 1949 - 1950; 73 if born 1951-1959; 75 if born 1960 or later.
  // Required beginning date (RBD) = April 1 of the year after the year the owner reaches it.
  // A Roth IRA owner has no lifetime RMDs, so is always treated as dying before the RBD.
  // Beneficiary rules: Treas. Reg. 1.401(a)(9)-3, -4(e) and -5(d)-(e) as amended by T.D. 10001
  // (final regulations, 89 FR 58886, July 19, 2024; apply to distribution years from 2025):
  //  - eligible designated beneficiary (EDB): surviving spouse, the owner's child under 21 (age of
  //    majority = 21st birthday), disabled, chronically ill, or born no more than 10 years after the
  //    owner (compared by dates of birth). EDBs take life-expectancy payments from the year after
  //    death. A minor child must empty the account by the end of the year containing the 10th
  //    anniversary of turning 21; annual payments continue until then.
  //  - any other designated beneficiary: empty by Dec 31 of the year containing the 10th
  //    anniversary of death; if the owner died on or after the RBD, annual RMDs in years 1-9 too.
  //  - no designated beneficiary (estate, charity, non-see-through trust): 5-year rule if the owner
  //    died before the RBD, otherwise the owner's remaining life expectancy.
  //  - after a death on or after the RBD the divisor is the greater of the beneficiary's and the
  //    owner's remaining life expectancy. Owner: Table I at age in the death year, minus 1 per later
  //    year. Non-spouse beneficiary: Table I at age in the year after death, minus 1 per later year
  //    (non-recalculating). Sole spouse: Table I at the spouse's age each year (recalculated).
  //  - an EDB of an owner who died before the RBD may elect the 10-year rule instead (no annual
  //    RMDs); a sole spouse may delay the start to the year the owner would have reached the
  //    applicable age (Treas. Reg. 1.401(a)(9)-3(d)).
  // Penalty relief: IRS Notices 2022-53, 2023-54 and 2024-35 - no excise tax for annual 10-year-rule
  // RMDs missed in 2021-2024 when the owner died in 2020-2023 on or after the RBD. Annual RMDs are
  // required from 2025 and the 10-year deadline does not move.
  var RELIEF_FIRST = 2021, RELIEF_LAST = 2024;
  var MAJORITY_AGE = 21;
  // --------------------------------------------------------------------------------------

  function lifeExp(age) {
    if (age < 0) age = 0;
    return age >= 120 ? SINGLE_LIFE[120] : SINGLE_LIFE[age];
  }
  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var y = +m[1], mo = +m[2], d = +m[3], t = new Date(Date.UTC(2000, mo - 1, d));
    if (mo < 1 || mo > 12 || d < 1 || t.getUTCMonth() !== mo - 1) return null;
    if (mo === 2 && d === 29 && !(y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0))) return null;
    return { y: y, m: mo, d: d };
  }
  function cmp(a, b) { return (a.y - b.y) || (a.m - b.m) || (a.d - b.d); }
  function plusYears(dt, n) { return { y: dt.y + n, m: dt.m, d: dt.d }; }
  // Calendar year in which a person born on `dob` reaches the RMD applicable age.
  function applicableYear(dob) {
    if (cmp(dob, { y: 1949, m: 7, d: 1 }) < 0) return dob.m <= 6 ? dob.y + 70 : dob.y + 71; // 70 1/2
    return dob.y + (dob.y <= 1950 ? 72 : dob.y <= 1959 ? 73 : 75);
  }
  // Works out which payout rule applies. inp: {roth, ownerDob, death, type, benDob}.
  function analyse(inp) {
    var D = inp.death.y, notes = [], type = inp.type;
    var appYear = applicableYear(inp.ownerDob), rbd = { y: appYear + 1, m: 4, d: 1 };
    var afterRbd = !inp.roth && cmp(inp.death, rbd) >= 0;
    if (type !== 'estate' && type !== 'spouse') {
      var within10 = cmp(inp.benDob, plusYears(inp.ownerDob, 10)) <= 0;
      if (type === 'minor' && cmp(inp.death, plusYears(inp.benDob, MAJORITY_AGE)) >= 0) {
        type = within10 ? 'close' : 'other';
        notes.push('The child was already 21 on the date of death, so the minor-child rule does not apply.');
      }
      if (type === 'other' && within10) {
        type = 'close';
        notes.push('The beneficiary was born no more than 10 years after the owner, which makes them an eligible designated beneficiary.');
      } else if (type === 'close' && !within10) {
        type = 'other';
        notes.push('The beneficiary was born more than 10 years after the owner, so the 10-year rule for other beneficiaries applies.');
      }
    }
    var ownerAgeD = D - inp.ownerDob.y;
    var benAgeNext = inp.benDob ? D + 1 - inp.benDob.y : 0;
    function ownerLE(y) { return lifeExp(ownerAgeD) - (y - D); }
    function benLE(y) { return lifeExp(benAgeNext) - (y - D - 1); }
    function spouseLE(y) { return lifeExp(y - inp.benDob.y); }
    function longer(f) { return function (y) { return Math.max(f(y), ownerLE(y)); }; }
    var s = { type: type, roth: inp.roth, afterRbd: afterRbd, rbd: rbd, appYear: appYear, deathYear: D, notes: notes,
              first: D + 1, final: null, annual: true, relief: false, div: null, rule: '', majority: null,
              canElect10: false, ownerLE0: lifeExp(ownerAgeD), benLE0: lifeExp(benAgeNext) };
    if (type === 'estate') {
      if (afterRbd) { s.rule = "Owner's remaining life expectancy"; s.div = ownerLE; }
      else { s.rule = '5-year rule'; s.annual = false; s.first = null; s.final = D + 5; }
    } else if (type === 'other') {
      s.final = D + 10;
      if (afterRbd) { s.rule = '10-year rule with annual RMDs'; s.div = longer(benLE); s.relief = D <= 2023; }
      else { s.rule = '10-year rule'; s.annual = false; s.first = null; }
    } else if (type === 'spouse') {
      s.rule = 'Life expectancy, recalculated yearly';
      s.div = afterRbd ? longer(spouseLE) : spouseLE;
      if (!afterRbd) s.first = Math.max(D + 1, appYear);
      s.canElect10 = !afterRbd;
    } else {
      s.rule = 'Life expectancy (stretch)';
      s.div = afterRbd ? longer(benLE) : benLE;
      s.canElect10 = !afterRbd;
      if (type === 'minor') {
        s.majority = inp.benDob.y + MAJORITY_AGE;
        s.final = s.majority + 10;
        s.rule = 'Life expectancy, then 10 years after age 21';
      }
    }
    return s;
  }
  // Required amount for distribution year y, given the balance on December 31 of year y - 1.
  function required(s, y, bal) {
    if (y <= s.deathYear) return { status: 'deathYear', amount: 0, divisor: null };
    if (s.final !== null && y > s.final) return { status: 'past', amount: bal, divisor: null };
    if (s.final !== null && y === s.final) return { status: 'final', amount: bal, divisor: null };
    if (!s.annual || y < s.first) return { status: 'none', amount: 0, divisor: null };
    var d = s.div(y);
    if (s.relief && y >= RELIEF_FIRST && y <= RELIEF_LAST) return { status: 'waived', amount: 0, divisor: d };
    if (d <= 1) return { status: 'all', amount: bal, divisor: d };
    return { status: 'annual', amount: bal / d, divisor: d };
  }

  // Projects required withdrawals from startYear (balance = Dec 31 of startYear - 1).
  function project(s, startYear, bal, rate, maxRows) {
    var y = startYear, b = bal, rows = [];
    if (y <= s.deathYear) { b *= Math.pow(1 + rate, s.deathYear + 1 - y); y = s.deathYear + 1; }
    for (var i = 0; i < maxRows && b > 0.005; i++, y++) {
      var q = required(s, y, b);
      if (q.status === 'past') break;
      var end = Math.max(0, b * (1 + rate));
      var w = (q.status === 'final' || q.status === 'all') ? end : Math.min(end, q.amount);
      rows.push({ year: y, start: b, divisor: q.divisor, status: q.status, rmd: w });
      b = Math.max(0, end - w);
    }
    return rows;
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function money(x) { return moneyFmt.format(isFinite(x) && Math.abs(x) >= 0.005 ? x : 0); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function val(id) { return document.getElementById(id).value; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fillRows(id, rows) {
    var body = document.getElementById(id);
    body.textContent = '';
    rows.forEach(function (cells) {
      var tr = document.createElement('tr');
      cells.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }
  function fillList(id, items) {
    var ul = document.getElementById(id);
    ul.textContent = '';
    items.forEach(function (t) { var li = document.createElement('li'); li.textContent = t; ul.appendChild(li); });
  }

  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September',
                'October', 'November', 'December'];
  function fmtDate(dt) { return MONTHS[dt.m - 1] + ' ' + dt.d + ', ' + dt.y; }
  function readInputs(p) {
    return { roth: val(p + 'Acct') === 'roth', ownerDob: parseDate(val(p + 'OwnerDob')),
             death: parseDate(val(p + 'Death')), type: val(p + 'Type'), benDob: parseDate(val(p + 'BenDob')) };
  }
  function checkInputs(inp) {
    if (!inp.ownerDob || inp.ownerDob.y < 1900) return "Enter the owner's date of birth.";
    if (!inp.death || inp.death.y < 2020 || inp.death.y > 2100)
      return 'Enter a date of death from 2020 to 2100. Deaths before 2020 follow the older stretch rules.';
    if (cmp(inp.death, inp.ownerDob) <= 0 || inp.death.y - inp.ownerDob.y > 120)
      return "The date of death must be after the owner's date of birth (age 120 or under).";
    if (inp.type !== 'estate') {
      if (!inp.benDob || inp.benDob.y < 1900) return "Enter the beneficiary's date of birth.";
      if (cmp(inp.benDob, inp.death) > 0) return "The beneficiary's date of birth must be on or before the owner's date of death.";
    } else {
      inp.benDob = null;
    }
    return '';
  }
  function rbdText(s) {
    return s.roth ? 'None (Roth IRA)' : fmtDate(s.rbd);
  }

  var STATUS_NOTE = { annual: '', waived: 'Excused (IRS relief)', none: 'None required', final: 'Empty the account',
                      all: 'Life expectancy used up' };

  function explain(s, inp, startYear) {
    var D = s.deathYear, out = [];
    if (s.roth) out.push('Roth IRA owners have no required beginning date, so the owner counts as dying before it.');
    else out.push("The owner's required beginning date was " + fmtDate(s.rbd) + ', so they died ' +
                  (s.afterRbd ? 'on or after it.' : 'before it.'));
    if (s.type === 'other' && s.afterRbd) {
      out.push('Annual RMDs are due for ' + (D + 1) + ' to ' + (D + 9) + ', and whatever is left must come out by December 31, ' + (D + 10) + '.');
      if (s.relief) out.push('Annual RMDs missed for 2021 to 2024 are excused under IRS Notices 2022-53, 2023-54 and 2024-35. They are required from 2025, and the ' + (D + 10) + ' deadline does not move.');
    } else if (s.type === 'other') {
      out.push('No withdrawal is required until ' + (D + 10) + ', when the whole account must be withdrawn. Spreading withdrawals over the 10 years can keep more of each year’s income in lower tax brackets.');
    } else if (s.type === 'estate' && !s.afterRbd) {
      out.push('The 5-year rule applies: the whole account must be withdrawn by December 31, ' + (D + 5) + ', with no minimum before then.');
    } else if (s.type === 'estate') {
      out.push("Withdrawals use the owner's remaining life expectancy: " + (s.ownerLE0 - 1).toFixed(1) + ' in ' + (D + 1) + ', reduced by 1 each year.');
    } else if (s.type === 'spouse') {
      out.push('As sole spouse beneficiary your divisor is looked up again each year from Table I at your age that year.');
      if (!s.afterRbd && s.first > D + 1) out.push('You can wait until ' + s.first + ', the year the owner would have reached RMD age, before RMDs start.');
      out.push('You can instead roll the account into your own IRA and follow the owner rules.');
    } else {
      out.push('As an eligible designated beneficiary you can stretch withdrawals over your life expectancy: ' +
               (s.benLE0).toFixed(1) + ' in ' + (D + 1) + ', reduced by 1 each year' +
               (s.afterRbd && s.ownerLE0 - 1 > s.benLE0 ? " (the owner's remaining life expectancy is longer and is used instead)." : '.'));
      if (s.type === 'minor') out.push('The child turns 21 in ' + s.majority + '. Annual RMDs continue after that, and the account must be empty by December 31, ' + s.final + '.');
    }
    if (s.canElect10) out.push('Because the owner died before the required beginning date, you may instead elect the 10-year rule (no annual RMDs; empty by December 31, ' + (D + 10) + '). The election is generally due by December 31, ' + (D + 1) + '.');
    if (s.afterRbd) out.push("The owner's own RMD for " + D + ', the year of death, was due by December 31, ' + D + '. Any part the owner had not taken had to be taken by the beneficiary.');
    if (startYear <= D) out.push('Beneficiary RMDs start after the year of death, so the schedule starts in ' + (D + 1) + ' and grows the balance at your expected return until then.');
    return out.concat(s.notes);
  }

  function update() {
    var inp = readInputs('bn'), year = Math.round(num('bnYear')), bal = num('bnBalance'), rate = num('bnRate');
    document.getElementById('bnBenDobWrap').hidden = inp.type === 'estate';
    set('bnBalanceLabel', 'Balance on December 31, ' + (isNaN(year) ? 'of the prior year' : year - 1));
    var err = checkInputs(inp);
    if (!err && ([year, bal, rate].some(isNaN) || year < 2021 || year > 2100 || bal < 0 || rate < -50 || rate > 30))
      err = 'Enter a first year from 2021 to 2100, a balance of $0 or more and a return from -50% to 30%.';
    var error = document.getElementById('bnError');
    error.hidden = !err;
    if (err) { error.textContent = err; return; }

    var s = analyse(inp), rows = project(s, year, bal, rate / 100, 100);
    var notes = explain(s, inp, year);
    set('bnRule', s.rule);
    set('bnDeadline', s.final !== null ? 'Dec 31, ' + s.final : 'No fixed deadline');
    var firstReq = s.annual ? (s.relief ? Math.max(s.first, RELIEF_LAST + 1) : s.first) : null;
    set('bnFirst', firstReq === null ? 'None' : String(firstReq));
    set('bnRbd', rbdText(s));
    if (s.final !== null && year > s.final) {
      set('bnRmdLabel', 'RMD for ' + year);
      set('bnRmd', money(bal));
      notes.unshift('The account should already have been emptied by December 31, ' + s.final + '. Withdraw the remaining balance and ask a tax adviser about the excise tax and a waiver request.');
    } else if (rows.length) {
      set('bnRmdLabel', 'RMD for ' + rows[0].year);
      set('bnRmd', money(rows[0].rmd));
    } else {
      set('bnRmdLabel', 'RMD for ' + Math.max(year, s.deathYear + 1));
      set('bnRmd', money(0));
    }
    set('bnTotal', money(rows.reduce(function (t, r) { return t + r.rmd; }, 0)));
    fillList('bnNotes', notes);
    fillRows('bnSchedule', rows.map(function (r) {
      var note = STATUS_NOTE[r.status] || '';
      if (s.majority !== null && r.year === s.majority) note = 'Child turns 21';
      return [String(r.year), inp.benDob ? String(r.year - inp.benDob.y) : '—', money(r.start),
              r.divisor === null ? '—' : r.divisor.toFixed(1), money(r.rmd), note];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('bnForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
